from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from .documents import AuditEventDocument

class AuditLogSearchView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        search_term = request.query_params.get("query", "")
        s = AuditEventDocument.search().filter(
            "term", org_id=request.user.organization_id
        ).query(
            "multi_match",
            query=search_term,
            fields=["action", "actor_email", "ip_address", "resource"]
        )
        response = s.execute()
        hits = [
            {
                "action": hit.action,
                "actor_email": hit.actor_email,
                "ip": hit.ip_address,
                "timestamp": hit.timestamp
            } for hit in response
        ]
        return Response({"hits": hits})
